def test_authenticated_progress_is_restored_after_login(client: TestClient) -> None:
    """An Account's accepted Guess is restored without trusting browser state."""
    client.post(
        "/api/auth/register",
        json={"username": "ResumePlayer", "password": "valid-password"},
    )
    challenge_date = current_challenge_date()
    pins = challenge_generator.generate(challenge_date)
    answer_ids = {pin.district.id for pin in pins}
    miss = next(district for district in catalog.districts if district.id not in answer_ids)

    guessed = client.post(
        "/api/daily/guess",
        json={
            "challenge_date": challenge_date.isoformat(),
            "guessed_district_id": miss.id,
            "anonymous_state": {
                "budget_remaining": 1,
                "solved_pin_indices": [0, 1, 2, 3],
            },
        },
    )
    client.cookies.clear()
    login = client.post(
        "/api/auth/login",
        json={"username": "ResumePlayer", "password": "valid-password"},
    )
    restored = client.get("/api/daily")

    assert guessed.status_code == 200
    assert guessed.json()["budget_remaining"] == 9
    assert guessed.json()["status"] == "in_progress"
    assert login.status_code == 200
    assert restored.status_code == 200
    assert restored.json()["state_source"] == "account"
    assert restored.json()["budget_remaining"] == 9
    assert restored.json()["status"] == "in_progress"
    assert restored.json()["solved_pins"] == []
    assert restored.json()["guess_history"] == [
        {
            "district_id": miss.id,
            "district_name": miss.name,
            "correct": False,
            "distance_km": guessed.json()["distance_km"],
            "solved_pin_index": None,
        }
    ]
    assert restored.json()["missed_districts"][0]["district_id"] == miss.id


def test_authenticated_finished_game_cannot_be_replayed(client: TestClient) -> None:
    """A finished Account Game remains finished and rejects later Guesses."""
    client.post(
        "/api/auth/register",
        json={"username": "DailyPlayer", "password": "valid-password"},
    )
    challenge_date = current_challenge_date()
    pins = challenge_generator.generate(challenge_date)
    answer_ids = {pin.district.id for pin in pins}
    misses = [district for district in catalog.districts if district.id not in answer_ids]

    for miss in misses[:10]:
        response = client.post(
            "/api/daily/guess",
            json={
                "challenge_date": challenge_date.isoformat(),
                "guessed_district_id": miss.id,
            },
        )
        assert response.status_code == 200

    client.cookies.clear()
    login = client.post(
        "/api/auth/login",
        json={"username": "DailyPlayer", "password": "valid-password"},
    )
    restored = client.get("/api/daily")
    replay = client.post(
        "/api/daily/guess",
        json={
            "challenge_date": challenge_date.isoformat(),
            "guessed_district_id": pins[0].district.id,
        },
    )

    assert login.status_code == 200
    assert restored.status_code == 200
    assert restored.json()["status"] == "finished"
    assert restored.json()["budget_remaining"] == 0
    assert len(restored.json()["solved_pins"]) == 5
    assert len(restored.json()["guess_history"]) == 10
    assert replay.status_code == 409
    assert replay.json() == {
        "detail": "Today's Daily Challenge is already finished",
        "code": "http.409",
    }
    with TestSession() as database:
        guess_count = database.scalar(
            select(func.count())
            .select_from(Guess)
            .join(GameDailyDistricts)
            .join(Account)
            .where(Account.username == "DailyPlayer")
        )
        assert guess_count == 10


