def test_generated_pins_keep_clear_of_district_boundaries() -> None:
    seeds = ["harbour-party", "friday-at-the-harbour", "narrow-district-check"]

    for district in catalog.districts:
        assert not district.pin_area_metric.is_empty
        assert PIN_BORDER_CLEARANCE_METERS <= district.pin_clearance_meters
        assert district.pin_clearance_meters <= PIN_BORDER_CLEARANCE_MAX_METERS

    clearances = {district.pin_clearance_meters for district in catalog.districts}
    assert min(clearances) == PIN_BORDER_CLEARANCE_METERS
    assert max(clearances) == PIN_BORDER_CLEARANCE_MAX_METERS

    for seed in seeds:
        for pin in challenge_generator.generate_seeded(seed):
            clearance = pin.point_metric.distance(pin.district.geometry_metric.boundary)
            assert clearance >= pin.district.pin_clearance_meters - 0.01


